from pysat.solvers import Glucose3
from pysat.formula import CNF

N = 22
# variables: x[r][c] = r*N + c + 1
def v(r,c): return r*N + c + 1

solver = Glucose3()

# exactly one per row
for r in range(N):
    solver.add_clause([v(r,c) for c in range(N)])
    for c1 in range(N):
        for c2 in range(c1+1,N):
            solver.add_clause([-v(r,c1), -v(r,c2)])

# at most one per column
for c in range(N):
    for r1 in range(N):
        for r2 in range(r1+1,N):
            solver.add_clause([-v(r1,c), -v(r2,c)])

# diagonals
for r1 in range(N):
    for c1 in range(N):
        for r2 in range(r1+1,N):
            for c2 in range(N):
                if abs(r1-r2)==abs(c1-c2):
                    solver.add_clause([-v(r1,c1), -v(r2,c2)])

# fixed
fixed = {11:8, 16:14, 18:11, 21:13}
for r,c in fixed.items():
    solver.add_clause([v(r,c)])

if solver.solve():
    m = solver.get_model()
    sol = [0]*N
    for r in range(N):
        for c in range(N):
            if m[v(r,c)-1] > 0:
                sol[r]=c
    print(sol)
else:
    print("UNSAT")
